begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email) values ('86000000-0000-4000-8000-000000000001','voucher-venues-admin@example.invalid'),('86000000-0000-4000-8000-000000000002','voucher-venues-td@example.invalid');
insert into public.profiles(id,full_name,role) values ('86000000-0000-4000-8000-000000000001','Venue admin','admin'),('86000000-0000-4000-8000-000000000002','TD staff','player') on conflict(id) do update set role=excluded.role;
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) select gen_random_uuid(),id,'totp','verified','LOCAL-TEST-ONLY',now(),now() from auth.users where id in ('86000000-0000-4000-8000-000000000001','86000000-0000-4000-8000-000000000002');
insert into public.staff_employee_profiles(profile_id,legal_name,department,active) values ('86000000-0000-4000-8000-000000000002','TD staff','VRena',true);
insert into public.staff_employee_locations values ('86000000-0000-4000-8000-000000000002','cafe-des-stagiaires');
insert into auth.users(id,email) select '86000000-0000-4000-8000-000000000003','contact@vre-vietnam.com' where not exists(select 1 from auth.users where email='contact@vre-vietnam.com');
insert into public.profiles(id,full_name,role) select id,'Shared test login','player' from auth.users where email='contact@vre-vietnam.com' on conflict(id) do nothing;
update public.staff_employee_profiles set kiosk_access_role='staff' where profile_id='86000000-0000-4000-8000-000000000002';
insert into private.staff_kiosk_pin_credentials(profile_id,pin_hash,access_role) values('86000000-0000-4000-8000-000000000002','TEST ONLY','staff');
insert into private.staff_kiosk_operator_sessions(auth_user_id,operator_profile_id,access_role,token_hash) select id,'86000000-0000-4000-8000-000000000002','staff',encode(extensions.digest('multi-venue-td-token','sha256'),'hex') from auth.users where email='contact@vre-vietnam.com';
select set_config('test.venue_staff_login',(select id::text from auth.users where email='contact@vre-vietnam.com'),true);

insert into public.staff_orders(id,order_number,booking_date,booking_time,players_count,total,subtotal,arena_id,payment_status,order_status,payment_method) values
 ('86000000-0000-4000-8000-000000000011','VENUE-VOUCHER-SOURCE',current_date,'10:00',1,300000,300000,'arena-1','paid','completed','cash'),
 ('86000000-0000-4000-8000-000000000012','VENUE-VOUCHER-TD',current_date,'10:00',1,50000,50000,'cafe:arena-1','unpaid','confirmed','unpaid');
select ok(not has_function_privilege('anon','public.staff_convert_payment_to_voucher(uuid,uuid,uuid,integer,text,integer,text[])','execute'),'Anonymous cannot select issuance venues');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"86000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
set local role authenticated;
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,gen_random_uuid(),100000,'Empty venues',30,array[]::text[])$q$,'P0001','Select at least one active venue.','Empty selection rejected');
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,gen_random_uuid(),100000,'Unknown venue',30,array['unknown'])$q$,'P0001','Select at least one active venue.','Unknown venue rejected');
select lives_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,'86000000-0000-4000-8000-000000000021',100000,'Both venues',90,array['ha-do-centrosa','cafe-des-stagiaires'])$q$,'Issue one voucher for both venues');

select ok(not has_function_privilege('anon','public.staff_manage_payment_voucher(uuid,uuid,text,text[],timestamptz,text)','execute'),'Anonymous cannot modify or delete credit');
select lives_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021','86000000-0000-4000-8000-000000000031','modify',array['cafe-des-stagiaires'],now()+interval '120 days','Change validity')$q$,'Modify valid venue and expiry');
select is((select valid_venue_keys from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),array['cafe-des-stagiaires'],'Selected modification saved');
select is((select amount from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),100000,'Modification preserves value');
select lives_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',null,'86000000-0000-4000-8000-000000000021',100000,'Both venues',90,array['ha-do-centrosa','cafe-des-stagiaires'])$q$,'Issuance retry remains valid after modifying venues');
select lives_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021','86000000-0000-4000-8000-000000000031','modify',array['cafe-des-stagiaires'],now()+interval '120 days','Change validity')$q$,'Lost modify response retries idempotently');
select throws_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021','86000000-0000-4000-8000-000000000031','modify',array['ha-do-centrosa'],now()+interval '120 days','Change validity')$q$,'P0001','Request reference already used.','Changed retry rejected');
select throws_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021',gen_random_uuid(),'modify',array['ha-do-centrosa'],now()-interval '1 day','Past expiry')$q$,'P0001','Choose a future expiry date or no expiry.','Past expiry cannot be set');
select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021',gen_random_uuid(),'modify',array['ha-do-centrosa','cafe-des-stagiaires'],null,'Restore both venues');
select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',(select id from public.staff_order_payments where order_id='86000000-0000-4000-8000-000000000011' and amount=300000),'86000000-0000-4000-8000-000000000041',50000,'Mistaken extra voucher',null,array['ha-do-centrosa']);
select set_config('test.deleted_code',(select code from public.payment_vouchers where id='86000000-0000-4000-8000-000000000041'),true);
select lives_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000041','86000000-0000-4000-8000-000000000042','delete',null,null,'Mistaken duplicate; no money restored')$q$,'Unused voucher permanently deletes');
select is((select count(*)::int from public.payment_vouchers where id='86000000-0000-4000-8000-000000000041'),0,'Deleted voucher row removed');
select is((select total from public.staff_orders where id='86000000-0000-4000-8000-000000000011'),150000,'Deletion does not restore order money');
select is((select sum(amount)::int from public.staff_order_payments where order_id='86000000-0000-4000-8000-000000000011'),150000,'Deletion does not restore paid balance');
select is((select amount from public.staff_order_payments where id='86000000-0000-4000-8000-000000000041'),-50000,'Original non-cash credit remains in ledger');
select is((select (public.staff_payment_voucher_deleted_credits('86000000-0000-4000-8000-000000000011')->>(select id::text from public.staff_order_payments where order_id='86000000-0000-4000-8000-000000000011' and amount=300000))::int),50000,'Deleted converted value remains consumed');
select lives_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000041','86000000-0000-4000-8000-000000000042','delete',null,null,'Mistaken duplicate; no money restored')$q$,'Lost delete response retries safely');
select is((select balance from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),100000,'Other voucher remains unchanged');
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',(select id from public.staff_order_payments where order_id='86000000-0000-4000-8000-000000000011' and amount=300000),'86000000-0000-4000-8000-000000000041',50000,'Mistaken extra voucher',null,array['ha-do-centrosa'])$q$,'P0001','Deleted voucher request cannot be reused.','Deleted issuance cannot be replayed');
update public.staff_orders set total=total+200000 where id='86000000-0000-4000-8000-000000000011';
insert into public.staff_order_payments(order_id,payment_method,amount) values('86000000-0000-4000-8000-000000000011','cash',200000);
select throws_ok($q$select public.staff_convert_payment_to_voucher('86000000-0000-4000-8000-000000000011',(select id from public.staff_order_payments where order_id='86000000-0000-4000-8000-000000000011' and amount=300000),gen_random_uuid(),175000,'Cannot reissue deleted credit',null,array['ha-do-centrosa'])$q$,'P0001','Amount exceeds the unconverted payment or order value.','Deleted credit cannot be converted again from original receipt');
select throws_ok($q$update public.staff_order_payments set amount=1 where order_id='86000000-0000-4000-8000-000000000011' and amount=300000$q$,'P0001','Voucher-linked receipts are immutable.','Deleted voucher retains original receipt protection');
reset role;
select ok(public.payment_voucher_quote(current_setting('test.deleted_code'),'ha-do-centrosa') ? 'error','Deleted bearer code no longer quotes');
select set_config('request.jwt.claims',jsonb_build_object('role','authenticated','sub',current_setting('test.venue_staff_login'),'aal','aal1')::text,true);
select set_config('request.headers','{"x-vrena-operator-session":"multi-venue-td-token"}',true);
set local role authenticated;
select throws_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021',gen_random_uuid(),'delete',null,null,'Forbidden source deletion')$q$,'P0001','Voucher not found or location access denied.','Other venue cannot manage source voucher');
reset role;
select set_config('test.used_code',(select code from public.payment_vouchers where id='86000000-0000-4000-8000-000000000021'),true);
select set_config('request.jwt.claims','{"role":"authenticated","sub":"86000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select public.staff_redeem_payment_voucher('86000000-0000-4000-8000-000000000012',current_setting('test.used_code'),gen_random_uuid(),1000);
select throws_ok($q$select public.staff_manage_payment_voucher('86000000-0000-4000-8000-000000000021',gen_random_uuid(),'delete',null,null,'Cannot erase used voucher')$q$,'P0001','Only unused vouchers can be deleted.','Used voucher history cannot be deleted');
select * from finish();
rollback;
